add_action( 'after_setup_theme', 'perfectpixel_register_shop_menu', 20 );
add_action( 'woocommerce_before_main_content', 'perfectpixel_output_shop_menu', 15 );

function perfectpixel_register_shop_menu() {
	register_nav_menu( 'perfectpixel_shop_menu', 'Μενού καταστήματος' );
}

function perfectpixel_output_shop_menu() {
	if ( has_nav_menu( 'perfectpixel_shop_menu' ) ) {
		wp_nav_menu(
			array(
				'theme_location'  => 'perfectpixel_shop_menu',
				'container'       => 'nav',
				'container_class' => 'perfectpixel-shop-menu',
				'menu_class'      => 'perfectpixel-shop-menu-list',
				'depth'           => 1,
			)
		);
		echo '<style>.perfectpixel-shop-menu-list{display:flex;flex-wrap:wrap;gap:.5em 1.5em;list-style:none;margin:0 0 1.5em;padding:0}</style>';
	}
}
